export interface ModelItem {
  id: string;
  title: string;
  category: string;
  sectionId: string;
  badge?: string;
  isHot?: boolean;
  driveUrl: string;
  downloadUrl?: string;
  imageUrl?: string;
  thumbnailUrl?: string;
  images?: string[];
  imageId?: string;
  stlId?: string;
  fileSize?: string;
  weightGrams?: number;
  filamentGrams?: number;
  printTimeHours?: number;
  suggestedPrice?: number;
  scale?: string;
  dimensions?: string;
  infill?: string;
  walls?: number;
  supports?: string;
  amsSupport?: boolean;
  colorTheme?: string;
  description?: string;
  commercialPermitted?: boolean;
  stlFiles?: Array<{ name: string; url: string; size?: string }>;
}

export interface SectionCategory {
  id: string;
  title: string;
  shortTitle: string;
  iconType: 'box' | 'zap' | 'shield' | 'sparkles' | 'sword' | 'trophy' | 'key' | 'gamepad' | 'bot' | 'lightbulb';
  accentColor: string;
  description: string;
  count: number;
  driveFolderUrl: string;
}

export interface LucrativeProduct {
  id: string;
  title: string;
  category: string;
  filamentGrams: number;
  salePrice: number;
  printHours: number;
  marginPercent: number;
}

